from ..widgets.widgets import Tooltip
from ..widgets.widgets import BetterCanvas

import tkinter as tk
import itertools
from tkinter import ttk

from PIL import Image, ImageTk
from pathlib import Path
import os


class SModsFrame(ttk.Frame):

    def __init__(self, parent, model, *args, **kwargs):
        super().__init__(parent, name="smod_frame_section", borderwidth=1, relief="ridge", *args, **kwargs)
        self.available_smods = list(model.bbmods_smods_info['SMODS'])
        self.smods_dictionary = {}
        self.smods_iterator = 1
        self.icons = self.__get_icons()
        self._setup()

    def get_smods(self):
        return self.smods_dictionary

    def get_configuration(self):
        return {k: v.get_smod_config() for k, v in sorted(self.smods_dictionary.items(), key=lambda item: item[0]) if v.is_configured}

    def _setup(self):
        smods_label = ttk.Label(
            self, text="SMOD TYPE", font=('Helvetica', 12, 'bold'), name='smod_frame_label'
        )
        separator = ttk.Separator(
            self, orient='horizontal', name="header_separator"
        )
        smods_canvas = BetterCanvas(
            self, bg="white", borderwidth=0, height=188, name="smods_canvas", width=210
        )
        smods_scrollbar = ttk.Scrollbar(
            self, orient=tk.VERTICAL, command=smods_canvas.yview, name="smods_scrollbar"
        )
        smods_frame = ttk.Frame(
            smods_canvas, name="smods_frame"
        )
        smods_canvas.create_window((0, 0), window=smods_frame)
        smods_canvas.configure(yscrollcommand=smods_scrollbar.set)

        smods_label.grid(column=0, row=0, sticky="sw", padx=(14, 0), ipady=10, columnspan=2)
        separator.grid(row=1, sticky="ew", columnspan=3)
        smods_canvas.grid(row=2, sticky="nsew", columnspan=3)
        smods_scrollbar.grid(row=2, column=2, sticky="nse")

        def update_canvas(_event):
            smods_canvas.configure(scrollregion=smods_canvas.bbox("all"))
            if smods_canvas.yview() == (0.0, 1.0):
                smods_canvas.yview_moveto(1.0)
        smods_frame.bind("<Configure>", update_canvas)  # is it necessary?

        self._add_smod()
        smods_canvas.bind('<Enter>', self._bound_to_mousewheel)
        smods_canvas.bind('<Leave>', self._unbound_to_mousewheel)

    @property
    def smods_canvas(self):
        return self.children['smods_canvas']

    @property
    def smods_scrollbar(self):
        return self.children['smods_scrollbar']

    def _bound_to_mousewheel(self, _event):
        self.smods_canvas.bind("<Button-4>", lambda event: self.smods_canvas.yview_scroll(int(-1 * event.num), 'units'))
        self.smods_canvas.bind("<Button-5>", lambda event: self.smods_canvas.yview_scroll(int(event.num), 'units'))

    def _unbound_to_mousewheel(self, _event):
        self.smods_canvas.unbind_all("<Button-4>")
        self.smods_canvas.unbind_all("<Button-5>")

    def _add_smod(self, smod_name=''):
        number_of_smods = len(self.smods_dictionary)
        next_smod_id = number_of_smods + 1

        parent = self.children['smods_canvas'].children['smods_frame']
        single_smod_frame = SingleSModFrame(
            parent, smod_name, self.available_smods, self.icons, text=f"SMOD-{next_smod_id}",
            borderwidth=0, font=('Helvetica 9'), bg='white', name=f"smod_{self.smods_iterator}"
        )
        self.smods_dictionary[next_smod_id] = single_smod_frame
        single_smod_frame.grid(column=0, row=next_smod_id, columnspan=3)
        self.smods_iterator += 1

    def _set_smod(self, smod_name):
        self.smods_dictionary[1].get_smod().set(smod_name)

    def reset(self):
        new_smods_dictionary = {}
        for i, smod in sorted(self.smods_dictionary.items(), key=lambda item: item[0]):
            if i == 1:
                smod._reset()
                new_smods_dictionary[1] = smod
            else:
                smod.destroy()
        self.smods_dictionary = new_smods_dictionary

    def rearrange(self):
        new_smods_dictionary = {}
        for i, (idx, smod) in zip(itertools.count(1), sorted(self.smods_dictionary.items(), key=lambda item: item[0])):
            smod.grid(row=i, sticky="new", column=0, columnspan=2)
            new_smods_dictionary[i] = smod
            smod.configure(text=f"SMOD-{i}")
        self.smods_scrollbar.set(0, 1)
        self.smods_dictionary = new_smods_dictionary

    def __get_icons(self):
        graphic_src_path = Path(os.path.abspath(__file__)).parents[1] / "graphics"

        minus_sign = Image.open(graphic_src_path / "large_minus.png").convert(mode='RGBA').resize((24, 24), Image.ANTIALIAS)
        minus_sign_image = ImageTk.PhotoImage(minus_sign)

        return {
            'smod_minus': minus_sign_image,
        }

    def set_smod(self, smod_name):
        self.smods_dictionary[1].get_smod().set(smod_name)

    def get_validation_log(self):
        return [f"SMOD-{k} is not configured" for k, v in sorted(self.smods_dictionary.items(), key=lambda item: item[0]) if not v.is_configured]


class SingleSModFrame(tk.LabelFrame):

    def __init__(self, parent, smod_name, available_smods, icons, **kwargs):
        super().__init__(parent, labelanchor="nw", **kwargs)
        self.available_smods = available_smods
        self.icons = icons
        self._initial_setup(smod_name)

    @property
    def is_configured(self):
        return bool(self.children['additional_smods_frame'].children['smod_combobox'].get())

    def get_smod_config(self):
        return self.children['additional_smods_frame'].children['smod_combobox'].get()

    def get_smod(self):
        return self.children['additional_smods_frame'].children['smod_combobox']

    def _initial_setup(self, smod_name):
        single_frame = ttk.Frame(
            self, name="additional_smods_frame"
        )
        smod_combobox = ttk.Combobox(
            single_frame, values=self.available_smods, width=19, state="readonly", name="smod_combobox"
        )
        Tooltip(smod_combobox, text='Set SMOD')
        smod_combobox.set(smod_name)
        single_frame.grid(row=0, column=0, columnspan=4)
        separator_h = ttk.Separator(self, orient='horizontal')
        smod_combobox.grid(row=0, column=0, columnspan=3)
        separator_h.grid(row=1, sticky="ew", columnspan=4)

    def _destroy_smod(self):
        number_of_configured_smods = len(self.__get_smods_frame().smods_dictionary)
        if number_of_configured_smods > 1:
            self._destroy()
        else:
            self._reset()

    def _destroy(self):
        configured_smods = self.__get_smods_frame().smods_dictionary
        current_id = self._get_current_id(configured_smods)
        configured_smods.pop(current_id)
        self.destroy()
        self.__get_smods_frame().rearrange()

    def _reset(self):
        self.children['additional_smods_frame'].children['smod_combobox'].set("")

    def _get_current_id(self, connections):
        for id_, connection in connections.items():
            if connection == self:
                return id_

    def __get_smods_frame(self):
        return self.master.master.master
